import { EXTENDED_INDIAN_RAILWAYS_TRAINS } from "./train-catalog";

export interface TrainEndpointStation {
  code: string;
  name: string;
  lat: number | null;
  lng: number | null;
}

export type CoachRole =
  | "locomotive"
  | "power"
  | "pantry"
  | "executive"
  | "ac"
  | "sleeper"
  | "general";

export interface CoachUnit {
  index: number; // 0-based position in rake (0 is Engine)
  coachOrderFromEngine: number; // 1-based coach count after Engine (0 for Engine)
  code: string;
  role: CoachRole;
  label: string;
}

export type TrainTrackingState =
  | "running"
  | "halted"
  | "not-started"
  | "completed"
  | "cancelled";

export interface NormalizedNextHalt {
  stationCode: string;
  stationName: string;
  sequence: number;
  distanceKm: number;
  distanceFromCurrentKm: number;
  scheduledArrival: string | null;
  expectedArrival: string | null;
  platform: string | null;
  delayMinutes: number;
}

export interface NormalizedCurrentLocation {
  stationCode: string;
  stationName: string;
  sequence: number;
  status: string;
  statusLabel: string;
  isHalt: boolean;
  lat: number | null;
  lng: number | null;
  distanceFromOriginKm: number;
  distanceFromLastStationKm: number;
  segmentProgress: number;
  speedKmh: number;
  delayMinutes: number;
}

export interface NormalizedLivePosition {
  trackingState: TrainTrackingState;
  isMoving: boolean;
  isHaltedAtStation: boolean;
  headline: string;
  subheadline: string;
  delayStatus: string;
  lastStation: {
    code: string;
    name: string;
    sequence: number;
    distanceKm: number;
    isHalt: boolean;
  } | null;
  nextStation: {
    code: string;
    name: string;
    sequence: number;
    distanceKm: number;
    isHalt: boolean;
  } | null;
  previousHalt: {
    code: string;
    name: string;
    sequence: number;
    distanceKm: number;
    departedAt: string | null;
    platform: string | null;
  } | null;
  distanceCoveredKm: number;
  distanceRemainingKm: number;
  distanceToNextHaltKm: number | null;
  haltSegmentProgress: number;
  betweenHaltAfterSeq: number | null;
  betweenAllAfterSeq: number | null;
  estimatedSpeedKmh: number;
  speedSource: "gps" | "section" | "average" | "stationary";
}

export interface NormalizedLiveSummary {
  trainLabel: string;
  routeLabel: string;
  currentStatusText: string;
  delayText: string;
  progressPercent: number;
  distanceCoveredKm: number;
  distanceTotalKm: number;
  distanceRemainingKm: number;
  haltsCompleted: number;
  haltsTotal: number;
  haltsRemaining: number;
  lastUpdatedIst: string;
}

export type RouteStopState = "departed" | "current" | "upcoming";

export interface NormalizedRouteStop {
  sequence: number;
  stationCode: string;
  stationName: string;
  isHalt: boolean;
  rawStatus: string;
  stopState: RouteStopState;
  coachPosition: string | null;
  lat: number | null;
  lng: number | null;
  scheduledArrival: string | null;
  actualArrival: string | null;
  arrivalDay: number;
  delayArrival: number;
  scheduledDeparture: string | null;
  actualDeparture: string | null;
  departureDay: number;
  delayDeparture: number;
  haltMinutes: number | null;
  platform: string | null;
  distanceKm: number;
  speedToNextStationKmph: number | null;
  provenance: string | null;
}

export interface NormalizedLiveTrainData {
  trainNumber: string;
  trainName: string;
  startDate: string;
  autoDetectedStartDate: boolean;
  lastUpdatedAt: string;
  status: string;
  statusLabel: string;
  trackingState: TrainTrackingState;
  isLive: boolean;
  trackingMode: string;
  delayMinutes: number;
  summary: NormalizedLiveSummary;
  livePosition: NormalizedLivePosition;
  train: {
    number: string;
    name: string;
    type: string;
    category: string;
    source: TrainEndpointStation;
    destination: TrainEndpointStation;
    runDays: string[];
    isDaily: boolean;
    distanceKm: number;
    durationMinutes: number;
    durationFormatted: string;
    avgSpeedKmph: number | null;
    maxSpeedKmph: number | null;
    totalHalts: number;
    totalRouteStations: number;
    returnTrain: string | null;
    coachPositionRaw: string | null;
    coaches: CoachUnit[];
  };
  nextHalt: NormalizedNextHalt | null;
  currentLocation: NormalizedCurrentLocation | null;
  geometry: {
    encodedPolyline: string | null;
    coordinates: Array<[number, number]>; // [lat, lng]
  };
  progressPercent: number;
  route: NormalizedRouteStop[];
  exceptions: string[];
}

export interface OwnedLiveTrainApiResponse {
  success: boolean;
  provider: "TravelAdda Owned Rail API v2";
  endpoint: string;
  data?: NormalizedLiveTrainData;
  error?: {
    code: string;
    message: string;
  };
  meta: {
    timestamp: string;
    traceId: string;
    source: string;
    executionTime: number;
    poweredBy: string;
    fetchedAt: string;
    responseTimeMs: number;
  };
}

export interface TrainSearchItem {
  trainNumber: string;
  trainName: string;
  sourceCode: string;
  sourceName: string;
  destinationCode: string;
  destinationName: string;
  type: string;
  runDays: string[];
  isDaily: boolean;
}

export interface OwnedTrainSearchApiResponse {
  success: boolean;
  provider: "TravelAdda Owned Rail API v2";
  query: string;
  count: number;
  data: TrainSearchItem[];
  meta: {
    fetchedAt: string;
    responseTimeMs: number;
  };
}

