export const ALL_CATALOG_TRAINS: TrainSearchItem[] = (() => {
  const seen = new Set<string>();
  const combined: TrainSearchItem[] = [];
  for (const train of [
    ...POPULAR_LIVE_TRAINS,
    ...EXTENDED_INDIAN_RAILWAYS_TRAINS,
  ]) {
    if (!seen.has(train.trainNumber)) {
      seen.add(train.trainNumber);
      combined.push(train);
    }
  }
  return combined;
})();

export const CATALOG_TRAIN_MAP: Map<string, TrainSearchItem> = (() => {
  const map = new Map<string, TrainSearchItem>();
  for (const t of ALL_CATALOG_TRAINS) {
    map.set(t.trainNumber, t);
  }
  return map;
})();

export const CATALOG_TRAIN_INDEX_MAP: Map<string, number> = (() => {
  const map = new Map<string, number>();
  ALL_CATALOG_TRAINS.forEach((t, idx) => {
    map.set(t.trainNumber, idx);
  });
  return map;
})();

export function findCatalogTrain(
  trainNumber: string
): TrainSearchItem | undefined {
  const clean = extractTrainNumberFromParam(trainNumber);
  return CATALOG_TRAIN_MAP.get(clean);
}

/**
 * Returns a deterministic connected mesh of related trains for internal SEO linking:
 * - Paired / return train number (±1)
 * - Adjacent ring-buffer trains in ALL_CATALOG_TRAINS so all 10,169+ trains form a 100% connected crawl graph
 * - Top flagship trains as hub anchors
 */
export function getRelatedCatalogTrains(
  trainNumber: string,
  limit = 16
): TrainSearchItem[] {
  const clean = extractTrainNumberFromParam(trainNumber);
  const total = ALL_CATALOG_TRAINS.length;
  if (total === 0) return [];

  const result: TrainSearchItem[] = [];
  const seen = new Set<string>([clean]);

  const pushTrain = (t: TrainSearchItem | undefined) => {
    if (t && !seen.has(t.trainNumber)) {
      seen.add(t.trainNumber);
      result.push(t);
    }
  };

  // 1. Return / paired train number (±1)
  const numVal = Number(clean);
  if (Number.isFinite(numVal) && numVal > 0) {
    const pairA = String(numVal % 2 === 0 ? numVal - 1 : numVal + 1);
    const pairB = String(numVal % 2 === 0 ? numVal + 1 : numVal - 1);
    pushTrain(CATALOG_TRAIN_MAP.get(pairA));
    pushTrain(CATALOG_TRAIN_MAP.get(pairB));
  }

  // 2. Ring-buffer neighbors around this train's index in ALL_CATALOG_TRAINS
  const startIdx =
    CATALOG_TRAIN_INDEX_MAP.get(clean) ??
    (Number.isFinite(numVal) ? numVal % total : 0);

  for (let offset = 1; offset <= limit + 8 && result.length < limit - 4; offset++) {
    const nextIdx = (startIdx + offset) % total;
    pushTrain(ALL_CATALOG_TRAINS[nextIdx]);
  }

  // 3. Anchor with top flagship trains
  for (let i = 0; i < POPULAR_LIVE_TRAINS.length && result.length < limit; i++) {
    pushTrain(POPULAR_LIVE_TRAINS[i]);
  }

  return result.slice(0, limit);
}

export function slugifyTrainName(name: string): string {
  return (name || "")
    .replace(/\([^)]*\)/g, " ")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-{2,}/g, "-");
}

export function extractTrainNumberFromParam(rawParam: string): string {
  const decoded = decodeURIComponent(rawParam || "").trim();
  const leadingMatch = /^(\d{3,5})(?:-|$)/.exec(decoded);
  if (leadingMatch) return leadingMatch[1];

  const anyNumberMatch = /\b(\d{4,5})\b/.exec(decoded);
  if (anyNumberMatch) return anyNumberMatch[1];

  const slugNeedle = slugifyTrainName(decoded);
  if (slugNeedle.length >= 3) {
    const matchedByName = ALL_CATALOG_TRAINS.find((t) => {
      const nameSlug = slugifyTrainName(t.trainName);
      return (
        nameSlug === slugNeedle ||
        nameSlug.includes(slugNeedle) ||
        slugNeedle.includes(nameSlug)
      );
    });
    if (matchedByName) return matchedByName.trainNumber;
  }

  return decoded.replace(/\D/g, "").slice(0, 5);
}

export function buildTrainSeoSlug(
  trainNumber: string,
  trainName?: string | null
): string {
  const cleanNum = extractTrainNumberFromParam(trainNumber);
  if (!cleanNum) return "";
  const catalogName = CATALOG_TRAIN_MAP.get(cleanNum)?.trainName;
  const resolvedName =
    catalogName ||
    (trainName &&
      !trainName.startsWith("Indian Railways Express #") &&
      trainName) ||
    "";
  const nameSlug = slugifyTrainName(resolvedName);
  if (!nameSlug || nameSlug === cleanNum) {
    return cleanNum;
  }
  const stripped = nameSlug.startsWith(`${cleanNum}-`)
    ? nameSlug.slice(cleanNum.length + 1)
    : nameSlug;
  return stripped ? `${cleanNum}-${stripped}` : cleanNum;
}

export function buildTrainLiveStatusPath(
  trainNumber: string,
  trainName?: string | null,
  date?: string | null
): string {
  const slug = buildTrainSeoSlug(trainNumber, trainName);
  if (!slug) return "/rail/live-status";
  const cleanDate =
    date && /^\d{4}-\d{2}-\d{2}$/.test(date.trim()) ? date.trim() : "";
  return cleanDate
    ? `/rail/live-status/${slug}?date=${cleanDate}`
    : `/rail/live-status/${slug}`;
}

